/* JINI AI-illustrated mascots (rabbit/cat/bear/fox; beginner, Lv50, Lv100).
   Art is embedded once, not fetched from a separate server. Existing saved characters,
   XP, avatar selection and unlocked wardrobe metadata remain untouched. */
(function(){
 "use strict";
 const SPECIES={rabbit:"토끼",cat:"고양이",bear:"곰",fox:"여우"};
 const Y={rabbit:"0%",cat:"33.333333%",bear:"66.666667%",fox:"100%"};
 const X=["0%","50%","100%"];
 const AURA={blue:"#d8e9ff",purple:"#edddff",pink:"#ffe2ee",mint:"#d5f8eb",yellow:"#fff1ce",black:"#e0e5ec"};
 const css=`
/* JINI hand-illustrated AI mascot sprite atlas. One image for all 12 evolutions. */
.jgc-mascot{display:block!important;position:relative;width:100%;height:100%;aspect-ratio:1;isolation:isolate;flex:none}
.jgc-mascot::before{content:"";position:absolute;inset:12%;border-radius:50%;background:radial-gradient(circle,var(--jgc-halo,#ede5ff) 0%,transparent 73%);filter:blur(10px);z-index:-1;pointer-events:none}
.jgc-mascot-illustration{display:block;position:absolute;inset:0;background-image:url("data:image/avif;base64,");background-repeat:no-repeat;background-size:300% 400%;background-position:var(--jgc-x,0%) var(--jgc-y,0%);image-rendering:auto;pointer-events:none}
.jgc-mascot.jgc-stars .jgc-mascot-illustration{filter:drop-shadow(0 0 5px #f0c772)}
.jgc-mascot.jgc-stars::after{content:"✦";position:absolute;top:7%;right:6%;font-size:18px;color:#e6b552;text-shadow:0 0 7px #f5da87;pointer-events:none}

/* Independently persisted equipment visual layers; the 3 evolution images stay separate. */
.jgc-mascot .jgc-gear-tint{filter:hue-rotate(var(--gear-hue)) saturate(1.18);z-index:2}
.jgc-tint-outfit{clip-path:ellipse(19% 19% at 51% 68%)}
.jgc-tint-bag{clip-path:ellipse(11% 12% at 35% 67%)}
.jgc-tint-book{clip-path:ellipse(10% 13% at 59% 68%)}
.jgc-worn{position:absolute;z-index:4;display:grid;place-items:center;font-family:"Apple Color Emoji","Segoe UI Emoji","Noto Color Emoji",sans-serif;font-size:calc(27px * var(--jgc-gear-scale,1));filter:drop-shadow(0 2px 2px #33234c50);pointer-events:none}
.jgc-mascot-stage-1{--jgc-gear-scale:.65}
.jgc-mascot-stage-2{--jgc-gear-scale:.85}
.jgc-mascot-stage-3{--jgc-gear-scale:1}
.jgc-worn-hat{top:26%;left:53%;transform:translateX(-50%) rotate(-13deg)}
.jgc-mascot-stage-3 .jgc-worn-hat{top:16%}
.jgc-worn-outfit{top:66%;left:48%}
.jgc-worn-bag{top:66%;left:30%}
.jgc-worn-book{top:65%;left:63%}
.jgc-mascot-stage-3 .jgc-worn-outfit{top:61%}
.jgc-mascot-stage-3 .jgc-worn-bag{top:63%}
.jgc-mascot-stage-3 .jgc-worn-book{top:62%}
`;
 const style=document.createElement("style");style.id="jini-ai-art-styles";style.textContent=css;document.head.appendChild(style);
 function render(config){
   config=config||{};
   const animal=Object.prototype.hasOwnProperty.call(SPECIES,config.avatar)?config.avatar:"rabbit";
   const level=Number(config.level)||1;
   const stage=level>=100?3:level>=50?2:1;
   const equipped=config.equipped||{};
   const extra="";
   const text=SPECIES[animal]+" "+(stage===1?"새싹":stage===2?"루키":"에이스")+" AI 일러스트 캐릭터";
   const halo=AURA[config.color]||AURA.blue;
   const adorn = {
     hat:{ribbon:"🎀",flower:"🌸",crown:"👑",scholar:"🎓"},
     outfit:{academy:"👕",robe:"🧥",royal:"👘"},
     bag:{backpack:"🎒",premium:"👜",explorer:"💼"},
     book:{special:"📘",royal:"📕",cosmic:"📙"}
   };
   const tint = {
     outfit:{academy:"0deg",robe:"205deg",royal:"276deg"},
     bag:{backpack:"0deg",premium:"80deg",explorer:"220deg"},
     book:{special:"205deg",royal:"310deg",cosmic:"70deg"}
   };
   let worn="";
   ["outfit","bag","book"].forEach(function(slot){
     const hue=tint[slot][equipped[slot]];
     if(hue)worn+='<span class="jgc-mascot-illustration jgc-gear-tint jgc-tint-'+slot+'" style="--gear-hue:'+hue+'" aria-hidden="true"></span>';
   });
   return '<span class="jgc-mascot jgc-mascot-stage-'+stage+extra+'" role="img" aria-label="'+text+'" style="--jgc-x:'+X[stage-1]+';--jgc-y:'+Y[animal]+';--jgc-halo:'+halo+'">'+
     '<span class="jgc-mascot-illustration" aria-hidden="true"></span>'+worn+'</span>';
 }
 function itemPreview(slot,id) {
   const icons={hat:{none:"—",ribbon:"🎀",flower:"🌸",crown:"👑",scholar:"🎓"},
     outfit:{basic:"👕",academy:"👔",robe:"🧥",royal:"👘"},
     bag:{none:"—",backpack:"🎒",premium:"👜",explorer:"💼"},
     book:{basic:"📖",special:"📘",royal:"📕",cosmic:"📙"}};
   const icon=icons[slot] && icons[slot][id] || "—";
   return '<span class="jgc-item-emoji" aria-hidden="true">'+icon+'</span>';
 }
 window.JINI_CHARACTER_ART={render:render,itemPreview:itemPreview,themes:Object.keys(AURA),species:Object.keys(SPECIES),style:"layered-illustration"};
}());
